const r = $input.first().json;
const ped = $('Receber pedido').first().json || {};
const NL = String.fromCharCode(10);
const nome = r.nome ? ', ' + r.nome : '';
const site = ped.origem === 'site';
const abertura = site
  ? 'Seu pedido para o *Beta fechado* do Dyno foi *aprovado*! 🎉'
  : 'Recebi uma solicitação de convite para você feita pelo CEO *Daniel Marim*. Seja muito bem-vindo! 🎉';
const t = 'Olá' + nome + '! 👋' + NL + 'Aqui é o *Dyno*, assessor pessoal no WhatsApp.' + NL + NL +
  abertura + NL + NL +
  'Com o Dyno você anota gastos por texto, áudio ou foto, recebe lembretes que insistem até você confirmar e organiza tarefas e contas a pagar, tudo por aqui.' + NL + NL +
  '📲 Antes de começar, siga o *@dynoapp.ia* no Instagram para receber dicas e novidades do Beta: https://instagram.com/dynoapp.ia' + NL + NL +
  'No Beta você tem *60 dias grátis*. Para ativar, é só responder *QUERO*. Seu convite (código ' + r.codigo + ') vale até ' + r.expira + '.' + NL + NL +
  (site ? 'Salve este número nos seus contatos como *Dyno* para não perder as mensagens.' : 'Se não tiver interesse, é só ignorar esta mensagem.');
return [{ json: { number: r.numero, text: String.fromCharCode(8203) + t, delay: 1200 } }];

const ped = $('Receber pedido').first().json;
const r = $('Supabase: criar convite').first().json || {};
let envio = null;
try { envio = $('Enviar ao convidado').first().json; } catch (e) { envio = null; }
const fmt = n => { const l = String(n || '').slice(2); return '+55 (' + l.slice(0, 2) + ') ' + (l.length === 11 ? l.slice(2, 7) + '-' + l.slice(7) : l.slice(2, 6) + '-' + l.slice(6)); };
let t;
if (r.ok === true) {
  if (envio && envio.key && !envio.error) {
    t = '✅ Convite enviado para *' + (r.nome_completo || 'a pessoa') + '* (' + fmt(r.numero) + '). Código ' + r.codigo + ', válido até ' + r.expira + '. Quando a pessoa responder, eu começo o cadastro com ela.' + (r.reenvio ? ' (O convite já existia; reenviei a mensagem.)' : '') + ' Vagas restantes: ' + r.vagas_restantes + '.';
  } else {
    t = '⚠️ Criei o convite ' + r.codigo + ' para ' + (r.nome_completo || 'a pessoa') + ', mas não consegui entregar a mensagem no ' + fmt(r.numero) + '. Confira se o número tem WhatsApp. Se preferir, encaminhe este link: https://wa.me/5511939497178?text=' + r.codigo;
  }
} else if (r.erro === 'ja_cadastrado') {
  t = 'ℹ️ Esse número já tem cadastro no Dyno (' + (r.nome || 'sem nome') + ', status ' + r.status + '). Não enviei convite.';
} else if (r.erro === 'numero_invalido') {
  t = '❌ Não entendi o número. Mande com DDD (ex.: 11 91234-5678) ou compartilhe o contato.';
} else if (r.erro === 'sem_vagas') {
  t = '❌ As vagas do piloto acabaram. Não enviei convite.';
} else {
  t = '❌ Não consegui criar o convite agora. Tente de novo em alguns minutos.';
}
return [{ json: { number: ped.numero_admin, text: String.fromCharCode(8203) + '*Dyno:* ' + t } }];
